diff --git a/client.mjs b/client.mjs
index 9ad81d0..fbaa42a 100644
--- a/client.mjs
+++ b/client.mjs
@@ -0,0 +1,2 @@
+import { sleep as realSleep } from './util.mjs';
+
@@ -12,4 +14,22 @@ export class HttpError extends Error {
-export async function fetchJson(url, { fetch = globalThis.fetch, headers = {} } = {}) {
-  const res = await fetch(url, { headers: { accept: 'application/json', ...headers } });
-  if (!res.ok) throw new HttpError(res.status, url);
-  return res.json();
+const MAX_RETRIES = 3;
+const BACKOFF_MS = 200;
+
+// Retries 503 and dropped connections (fetch rejects) up to 3 times with
+// exponential backoff. Other statuses (incl. 4xx) throw immediately.
+export async function fetchJson(url, { fetch = globalThis.fetch, headers = {}, sleep = realSleep } = {}) {
+  for (let attempt = 0; ; attempt++) {
+    let res;
+    try {
+      res = await fetch(url, { headers: { accept: 'application/json', ...headers } });
+    } catch (err) {
+      if (attempt >= MAX_RETRIES) throw err;
+      await sleep(BACKOFF_MS * 2 ** attempt);
+      continue;
+    }
+    if (res.status === 503 && attempt < MAX_RETRIES) {
+      await sleep(BACKOFF_MS * 2 ** attempt);
+      continue;
+    }
+    if (!res.ok) throw new HttpError(res.status, url);
+    return res.json();
+  }
diff --git a/client.test.mjs b/client.test.mjs
index b10d2e2..dedc42a 100644
--- a/client.test.mjs
+++ b/client.test.mjs
@@ -19,0 +20,22 @@ test('throws HttpError on non-2xx', async () => {
+test('fetchJson retries 503 and dropped connections with backoff', async () => {
+  const steps = [() => respond(503), () => { throw new TypeError('fetch failed'); }, () => respond(200, { ok: 1 })];
+  const fetch = async () => steps.shift()();
+  const naps = [];
+  assert.deepEqual(await fetchJson('https://x', { fetch, sleep: async (ms) => naps.push(ms) }), { ok: 1 });
+  assert.deepEqual(naps, [200, 400]);
+});
+
+test('fetchJson gives up after 3 retries', async () => {
+  let calls = 0;
+  const fetch = async () => { calls++; return respond(503); };
+  await assert.rejects(fetchJson('https://x', { fetch, sleep: async () => {} }), (err) => err.status === 503);
+  assert.equal(calls, 4);
+});
+
+test('fetchJson does not retry 4xx', async () => {
+  let calls = 0;
+  const fetch = async () => { calls++; return respond(404); };
+  await assert.rejects(fetchJson('https://x', { fetch, sleep: async () => {} }));
+  assert.equal(calls, 1);
+});
+
