+// Retries 503 and network failures (fetch rejecting) up to 3 times; other statuses throw at once.
+export async function fetchJson(url, { fetch = globalThis.fetch, headers = {}, sleep = realSleep, retries = 3 } = {}) {
+  for (let attempt = 0; ; attempt++) {
+    let res;
+    try {
+      res = await fetch(url, { headers: { accept: 'application/json', ...headers } });
+    } catch (err) {
+      if (attempt >= retries) throw err;
+      await sleep(200 * 2 ** attempt);
+      continue;
+    }
+    if (res.status === 503 && attempt < retries) {
+      await sleep(200 * 2 ** attempt);
+      continue;
+    }
+    if (!res.ok) throw new HttpError(res.status, url);
+    return res.json();
+  }
