+test('fetchJson gives up after 3 retries and does not retry 4xx', async () => {
+  let calls = 0;
+  const naps = [];
+  const sleep = async (ms) => naps.push(ms);
+  await assert.rejects(fetchJson('https://x', { fetch: async () => (calls++, respond(503)), sleep }), (e) => e.status === 503);
