+// Retries 503s and dropped connections up to `retries` times with exponential backoff.
+// Other statuses (4xx etc.) throw immediately. `sleep` is injectable so tests don't wait.
+export async function fetchJson(
+  url,
+  { fetch = globalThis.fetch, headers = {}, sleep = realSleep, retries = 3, backoff = 200 } = {},
+) {
+  for (let attempt = 0; ; attempt++) {
+    let res;
+    try {
+      res = await fetch(url, { headers: { accept: 'application/json', ...headers } });
+    } catch (err) {
+      if (attempt >= retries) throw err;
+      await sleep(backoff * 2 ** attempt);
+      continue;
+    }
+    if (res.status === 503 && attempt < retries) {
+      await sleep(backoff * 2 ** attempt);
+      continue;
+    }
+    if (!res.ok) throw new HttpError(res.status, url);
+    return res.json();
+  }
